# PDP URL shape on www.dyson.in. Anchor + embedded-config candidates MUST match
# one of these to count as product links. Two live shapes exist:
#   3-segment: /air-treatment/purifiers/purifier-cool-pc2-de-nox-white-gold
#   2-segment: /purifier-cool-pc2-de-nox-white-gold   (JSON-LD offers.url /
#              link[rel=canonical] form — short utility pages are excluded by
#              the 16-char slug floor and the negative filter below)
PDP_URL_RE = re.compile(
    r"^https?://(?:www\.)?dyson\.in/"
    r"(?:"
    r"(?:air-treatment|hair-care|vacuums|floor-care|lighting|wearables|accessories|shop-all[^/]*)"
    r"/[a-z0-9][a-z0-9-]*/[a-z0-9][a-z0-9-]{8,}"
    r"|"
    r"[a-z0-9][a-z0-9-]{15,}"
    r")(?:\?.*)?$"
)
# Anything landing on a listing/utility rail is never a product page.
PDP_URL_NEGATIVE_RE = re.compile(
    r"(?:/overview|/research|/accessories?(?:/|$)|/compare|/support|/faq"
    r"|/warranty|/register|/login|/account|/cart|/checkout|/blog|/story"
    r"|/guide|/newsroom|/terms|/privacy|/-recertified|/demo"
    r"|-filter-research|/shop-all-air-purifiers)"
)

# The verbatim job URL: a known-good PDP used as a discovery safety net.
ANCHOR_PRODUCT_URL = (
    "https://www.dyson.in/air-treatment/purifiers/purifier-cool-pc2-de-nox-white-gold"
)


def _looks_like_pdp(url: str) -> bool:
    if not PDP_URL_RE.search(url):
        return False
    if PDP_URL_NEGATIVE_RE.search(url):
        return False
    return True


def _collect_candidate_urls(soup: BeautifulSoup) -> list:
    """Every http(s) URL string appearing ANYWHERE in the page — anchors,
    buttons, data attributes, inline scripts, JSON-LD, iframe srcs. Magento's
    CSR grids keep their card config in embedded JSON islands, so a
    DOM-anchor-only sweep selects 0 links on this site (probed live)."""
    urls = []
    for a in soup.find_all("a"):
        href = a.get("href") or ""
        if href.startswith("http"):
            urls.append(href)
        elif href.startswith("/"):
            urls.append(urljoin(SITE_URL, href))
    for el in soup.find_all(True):
        for attr in ("data-url", "data-href", "data-product-url", "data-link"):
            val = el.get(attr)
            if val and val.startswith("/"):
                urls.append(urljoin(SITE_URL, val))
    for script in soup.find_all("script"):
        if script.get("type") in ("application/ld+json", "application/json"):
            continue  # handled separately below / by the shared ItemList fallback
        txt = script.string or ""
        if "dyson.in" not in txt and "/air-treatment" not in txt:
            continue
        for m in re.finditer(r'https?://[A-Za-z0-9.-]*dyson\.in/[^"\'\\\s<>)]+', txt):
            urls.append(m.group(0).rstrip(".,;"))
    return urls


def _extract_jsonld_products(soup: BeautifulSoup) -> list:
    """All Product-typed JSON-LD nodes (the site ships one per PDP)."""
    products = []
    for script in soup.find_all("script", type="application/ld+json"):
        raw = script.string or script.get_text() or ""
        if not raw.strip():
            continue
        try:
            data = json.loads(raw)
        except (json.JSONDecodeError, TypeError):
            continue
        nodes = data if isinstance(data, list) else [data]
        for node in nodes:
            if not isinstance(node, dict):
                continue
            if "Product" in (node.get("@type") if isinstance(node.get("@type"), list) else [node.get("@type")]):
                products.append(node)
    return products


def extract_jsonld(soup: BeautifulSoup) -> Optional[dict]:
    """Single Product JSON-LD node for this PDP (first match)."""
    products = _extract_jsonld_products(soup)
    return products[0] if products else None


def extract_product_from_page(soup: BeautifulSoup, url: str, status_code: int, src_url: str) -> dict:
    product = {
        "id": 0,
        "title": "",
        "price": "",
        "availability": "",
        "original_price": "",
        "currency": "",
        "url": url,
        "src_url": src_url,
        "location": "",
        "status_code": status_code,
        "scraped_at": datetime.now(timezone.utc).isoformat(),
        "remarks": "",
    }

    jsonld = extract_jsonld(soup)

    # ── Soft-404 detection — BEFORE field extraction ────────────────────────
    # ( Magento serves HTTP 200 for dead PDPs. )
    page_text = ""
    h1_el = soup.find("h1")
    h1_text = h1_el.get_text(strip=True) if h1_el else ""
    title_tag = soup.title.get_text(strip=True) if soup.title else ""
    try:
        body = soup.find("body")
        page_text = body.get_text(" ", strip=True) if body else ""
    except Exception:
        page_text = ""
    soft404 = False
    soft404_reason = ""
    if jsonld is None:
        # No Product JSON-LD anywhere: either a soft-404 shell or a non-PDP.
        if re.search(r"not\s*found|no\s*longer\s*available|unavailable|discontinued",
                     f"{title_tag} {h1_text}", re.I):
            soft404 = True
            soft404_reason = "Soft 404: no Product JSON-LD + 'not found' page title"
        else:
            soft404 = True
            soft404_reason = "Soft 404: no Product JSON-LD on page"
    elif re.search(r"not\s*found|no\s*longer\s*available|discontinued",
                   f"{title_tag} {h1_text}", re.I):
        soft404 = True
        soft404_reason = "Soft 404: page title/H1 says not found/discontinued"
    if soft404:
        product["remarks"] = soft404_reason
        return product

    offers = jsonld.get("offers", {}) or {}
    if isinstance(offers, list):
        offers = offers[0] if offers else {}

    # Title
    product["title"] = (jsonld.get("name") or "").strip() or (h1_text or title_tag.split(" | ")[0]).strip()

    # Price — JSON-LD first (authoritative), DOM price box as fallback.
    price_raw = offers.get("price", "")
    product["price"] = _norm_price(price_raw) or ""
    if not product["price"]:
        price_el = soup.select_one(".price-box .price-final_price .price")
        if not price_el:
            price_el = soup.select_one('[data-price-type="finalPrice"] .price')
        if price_el:
            product["price"] = _norm_price(price_el.get_text(strip=True)) or ""

    # Original price — only when a LOWER current price exists (sale state).
    # [dyson.in probed] This catalogue currently renders NO oldPrice nodes, so
    # this is future-proofing, not a live selector: guard every read.
    original_candidates = []
    for sel in ('[data-price-type="oldPrice"] .price', ".price-box .old-price .price"):
        el = soup.select_one(sel)
        if el:
            original_candidates.append(_norm_price(el.get_text(strip=True)))
    original_candidates = [c for c in original_candidates if c]
    if original_candidates and product["price"]:
        try:
            if max(float(c) for c in original_candidates) > float(product["price"]):
                product["original_price"] = max(original_candidates, key=float)
        except (TypeError, ValueError):
            pass

    # Currency — JSON-LD first, ₹/Rs lead as DOM fallback.
    product["currency"] = (offers.get("priceCurrency") or "").strip()
    if not product["currency"]:
        price_el = soup.select_one(".price-box .price-final_price .price")
        text = price_el.get_text(strip=True) if price_el else ""
        if text.startswith("₹") or "Rs" in text[:4]:
            product["currency"] = "INR"
    if not product["currency"]:
        product["currency"] = "INR"  # dyson.in catalog is INR-only

    # Availability — JSON-LD Offer.availability (schema.org URI), DOM fallback.
    product["availability"] = _norm_availability(offers.get("availability"))
    if not product["availability"]:
        if soup.select_one(".product__action__add-to-cart-notifyme"):
            product["availability"] = "out_of_stock"
        elif soup.select_one("#product-addtocart-button"):
            product["availability"] = "in_stock"

    # Description — meta description (JSON-LD description is EMPTY on this site).
    meta_desc = soup.select_one('meta[name="description"]')
    product["description"] = (
        meta_desc.get("content", "").strip() if meta_desc else ""
    )

    # Brand / SKU — JSON-LD (not rendered in the DOM on this theme).
    brand = jsonld.get("brand") or {}
    if isinstance(brand, dict):
        product["brand"] = (brand.get("name") or "").strip()
    elif isinstance(brand, str):
        product["brand"] = brand.strip()
    product["sku"] = (jsonld.get("sku") or "").strip()

    # Images — JSON-LD image array ONLY (Adobe Dynamic Media CDN), scoped to
    # the PDP's own primary images: never nav/hero/related thumbs. Plain
    # DOM-gallery scraping here would drag in client-rendered slick-carousel
    # clones (duplicate srcs) and off-product rails, so JSON-LD is the safe
    # product-gallery source on this theme.
    image_urls = []
    raw_images = jsonld.get("image")
    if isinstance(raw_images, str):
        raw_images = [raw_images]
    if isinstance(raw_images, list):
        for img in raw_images:
            abs_img = make_absolute_url(str(img))
            if not abs_img.startswith("http"):
                continue
            low = abs_img.lower()
            if any(bad in low for bad in (
                "/brand.assets/", "/emoji/", "/flags/", "/icon", "/navigation/",
                "logo", "banner", "placeholder", "sprite",
            )):
                continue
            if abs_img not in image_urls:
                image_urls.append(abs_img)
    product["images"] = image_urls[:15]

    # Category — derive from the URL path (this theme renders no breadcrumbs).
    path_parts = [p for p in url.split("://", 1)[-1].split("/", 1)]
    path = "/" + (path_parts[1] if len(path_parts) > 1 else "")
    product["category"] = " > ".join(
        p.replace("-", " ").strip().title()
        for p in path.strip("/").split("/")
        if p
    )

    return product


