PRODUCT_URL_RE = PDP_URL_RE


def _extract_listing_links(soup: BeautifulSoup) -> list:
    """The ONLY site-adaptable discovery code: this page's product URLs.

    Contract: return a list of ABSOLUTE urls (dupes fine — the shared module
    dedupes). Return [] when the page carries no product links; NEVER raise.
    An empty result makes the module do exactly one of two things before it
    gives up: check the page's JSON-LD ItemList (hidden-SSR listings embed
    their item set there even when the visible grid hydrates client-side),
    or escalate the proxy tier (200-but-zero-links soft-block signature).

    dyson.in specifics (live-probed): BOTH catalog pages
    (/air-treatment/purifiers landing and /air-treatment/shop-all-air-purifiers
    grid) are client-rendered shells under direct HTTP — the product data
    lives in embedded config islands, not <a href> markup. So this callback
    deep-scans every anchor, data-* URL, and inline script for PDP-shaped
    URLs, filtered by the site's PDP pattern.
    """
    # # Code Writer adapted: dyson.in deep-scan discovery (CSR catalog pages)
    urls = _collect_candidate_urls(soup)

    # PDP-shaped candidates only (regex is the same one shared discovery
    # applies to JSON-LD ItemList candidates, so anchor and ItemList paths
    # stay shape-consistent).
    found = set()
    for u in urls:
        absolute = make_absolute_url(u)
        if _looks_like_pdp(absolute):
            found.add(absolute.rstrip("/"))

    # Known-good safety net: the verbatim job URL is a PDP on this site; if
    # its listing/rail mentions it anywhere (e.g. as a relatedProducts target),
    # pin it into the result set even if the pattern mis-fires on a variant
    # spelling.
    if ANCHOR_PRODUCT_URL in " ".join(urls) or ANCHOR_PRODUCT_URL in str(soup):
        found.add(ANCHOR_PRODUCT_URL)

    return sorted(found)


